import tkinter as tk
from tkinter import messagebox
import secrets
import string
import tempfile
import base64
import sys
import os
ICON_DATA = b""""""

def write_temp_icon():
    with tempfile.NamedTemporaryFile(delete=False, suffix=".ico") as tmp:
        tmp.write(base64.b64decode(ICON_DATA))
        return tmp.name

icon_path = write_temp_icon()

def generate_password(length=11):
    if length < 4:
        return "길이가 너무 짧습니다!"
    upper = secrets.choice(string.ascii_uppercase)
    lower = secrets.choice(string.ascii_lowercase)
    digit = secrets.choice(string.digits)
    special = secrets.choice('!@#$%^&*()-_=+[]{}|;:,.<>?/`~')
    alphabet = string.ascii_letters + string.digits + '!@#$%^&*()-_=+[]{}|;:,.<>?/`~'
    remaining = [secrets.choice(alphabet) for _ in range(length - 4)]
    password_list = list(upper + lower + digit + special + ''.join(remaining))
    secrets.SystemRandom().shuffle(password_list)
    return ''.join(password_list)

def show_toast(msg):
    toast = tk.Toplevel(root)
    toast.overrideredirect(True)
    toast.attributes("-alpha", 0.0)
    toast.configure(bg='black')
    label = tk.Label(toast, text=msg, bg='black', fg='white', font=("맑은 고딕", 10))
    label.pack(ipadx=15, ipady=5)

    root.update_idletasks()
    x = root.winfo_x() + (root.winfo_width() // 2) - (label.winfo_reqwidth() // 2) -20
    y = root.winfo_y() + (root.winfo_height() // 2) - (label.winfo_reqheight() // 2) -30
    toast.geometry(f"+{x}+{y}")

    def fade_in(alpha=0.0):
        alpha += 0.1
        if alpha <= 0.9:
            toast.attributes("-alpha", alpha)
            toast.after(30, fade_in, alpha)
        else:
            toast.after(1000, fade_out)

    def fade_out(alpha=0.9):
        alpha -= 0.1
        if alpha > 0:
            toast.attributes("-alpha", alpha)
            toast.after(30, fade_out, alpha)
        else:
            toast.destroy()

    fade_in()

def on_generate():
    try:
        length = int(entry_length.get())
        if length < 6:
            entry_result.config(state="normal")
            entry_result.delete(0, tk.END)
            entry_result.insert(0, "6자리 이상 입력해주세요.")
            entry_result.config(state="readonly")
            return
        password = generate_password(length)
        entry_result.config(state="normal")
        entry_result.delete(0, tk.END)
        entry_result.insert(0, password)
        entry_result.config(state="readonly")
        root.clipboard_clear()
        root.clipboard_append(password)
        show_toast("복사 완료!")
    except ValueError:
        entry_result.config(state="normal")
        entry_result.delete(0, tk.END)
        entry_result.insert(0, "숫자를 입력해주세요.")
        entry_result.config(state="readonly")

